function _depositFor(
 uint256 _tokenId,
 uint256 _value,
 uint256 _unlockTime,
    LockedBalance memory _lock,
    DepositType _type
) internal {
    LockedBalance memory lock = _lock;
 uint256 supplyBefore = supply;
    supply = supplyBefore + _value;
